// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new PoCGame(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(bool transferResult, uint256 tokens, address tokenOwner) public {
        uint256 _tokens = bound(tokens, 0, 1e30);
        FakeToken t = new FakeToken(transferResult);
        vm.prank(address(uint160(0xE0A)));
        bool success = c.transferAnyERC20Token(address(t), tokenOwner, _tokens);
        assertTrue(success == transferResult, "return value must be propagated from token transfer");
    }
}

contract FakeToken {
    bool private _result;
    constructor(bool r) { _result = r; }
    function transfer(address, uint256) external returns (bool) { return _result; }
}
